'use client';
import {
  motion,
  MotionConfig,
  Transition,
  useReducedMotion,
} from 'motion/react';
import { motionElementOf } from './motion-elements';
import { cn } from '@/lib/utils';

export type TextShimmerWaveProps = {
  children: string;
  as?: React.ElementType;
  className?: string;
  duration?: number;
  zDistance?: number;
  xDistance?: number;
  yDistance?: number;
  spread?: number;
  scaleDistance?: number;
  rotateYDistance?: number;
  transition?: Transition;
};

function ReducedMotionConfig({ children }: { children: React.ReactNode }) {
  const prefersReducedMotion = useReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

export function TextShimmerWave({
  children,
  as: Component = 'p',
  className,
  duration = 1,
  zDistance = 10,
  xDistance = 2,
  yDistance = -2,
  spread = 1,
  scaleDistance = 1.1,
  rotateYDistance = 10,
  transition,
}: TextShimmerWaveProps) {
  const MotionComponent = motionElementOf(Component) as typeof motion.p;

  return (
    <ReducedMotionConfig>
      <MotionComponent
        className={cn(
          'relative inline-block [perspective:500px]',
          '[--base-color:var(--muted-foreground)] [--base-gradient-color:var(--foreground)]',
          className
        )}
        style={{ color: 'var(--base-color)' }}
      >
        {children.split('').map((char, i) => {
          const delay = (i * duration * (1 / spread)) / children.length;

          return (
            <motion.span
              key={i}
              className={cn(
                'inline-block whitespace-pre [transform-style:preserve-3d]'
              )}
              initial={{
                translateZ: 0,
                scale: 1,
                rotateY: 0,
                color: 'var(--base-color)',
              }}
              animate={{
                translateZ: [0, zDistance, 0],
                translateX: [0, xDistance, 0],
                translateY: [0, yDistance, 0],
                scale: [1, scaleDistance, 1],
                rotateY: [0, rotateYDistance, 0],
                color: [
                  'var(--base-color)',
                  'var(--base-gradient-color)',
                  'var(--base-color)',
                ],
              }}
              transition={{
                duration: duration,
                repeat: Infinity,
                repeatDelay: (children.length * 0.05) / spread,
                delay,
                ease: 'easeInOut',
                ...transition,
              }}
            >
              {char}
            </motion.span>
          );
        })}
      </MotionComponent>
    </ReducedMotionConfig>
  );
}

import { motion } from 'motion/react';

const MOTION_ELEMENTS = {
  a: motion.a,
  article: motion.article,
  aside: motion.aside,
  blockquote: motion.blockquote,
  button: motion.button,
  code: motion.code,
  div: motion.div,
  em: motion.em,
  figure: motion.figure,
  footer: motion.footer,
  h1: motion.h1,
  h2: motion.h2,
  h3: motion.h3,
  h4: motion.h4,
  h5: motion.h5,
  h6: motion.h6,
  header: motion.header,
  label: motion.label,
  li: motion.li,
  main: motion.main,
  nav: motion.nav,
  ol: motion.ol,
  p: motion.p,
  pre: motion.pre,
  section: motion.section,
  small: motion.small,
  span: motion.span,
  strong: motion.strong,
  ul: motion.ul,
};

type MotionElementTag = keyof typeof MOTION_ELEMENTS;

function isMotionElementTag(tag: unknown): tag is MotionElementTag {
  const isString = typeof tag === 'string';
  return isString && tag in MOTION_ELEMENTS;
}

/**
 * The motion version of an HTML tag. A lookup such as `motion[tag]` is invisible to the bundler,
 * which drops the tags it never sees and breaks the production build, so every tag is listed here.
 */
export function motionElementOf(tag: unknown) {
  if (isMotionElementTag(tag)) {
    return MOTION_ELEMENTS[tag];
  }
  return MOTION_ELEMENTS.div;
}
